"""Documentacao da 209a leva. Uso: python docs.py"""
import os, sys
sys.path.insert(0, os.path.join(os.path.dirname(os.path.abspath(__file__)), '..', '..', 'engenharia-reversa'))
from gen_docs import fazer, leia, cadeia

N = 209
R = [('montar_tela_da_partida', 'build_match_screen', '0x718e90', 'match_screens.cpp', 'cdecl', 'monta a tela da partida ao vivo: cabeçalhos dos times e placar, narração, relógio, controle, botões táticos, velocidades da narração, abas, o painel da aba, o estádio e o painel de narração', 'builds the live match screen: team headers and score, commentary, clock, control, tactics buttons, commentary speeds, tabs, the selected tab panel, the stadium and the commentary panel'), ('responder_tela_da_partida', 'handle_match_screen_input', '0x71a240', 'match_screens.cpp', 'cdecl', 'responde na tela da partida ao vivo: volume e velocidade da narração, o lance novo (relógio, narração, modos), assistir ou não, a tática de um time, a troca de aba e as respostas de cada aba', "handles the live match screen: commentary volume and speed, the new event (clock, commentary, modes), watching or not, a team's tactics, switching tabs and each tab's input"), ('montar_detalhes_da_partida', 'build_match_details_screen', '0x71b630', 'match_screens.cpp', 'cdecl', 'monta a tela de detalhes de uma partida guardada: lê o registro e a foto da partida nas estatísticas, os cabeçalhos dos times, as 7 abas e o painel da aba', 'builds the details screen of a stored match: loads the match record and snapshot from the match stats, the team headers, the 7 tabs and the selected tab panel'), ('atualizar_barra_da_posse', 'refresh_possession_bar', '0x71d9e0', 'match_screens.cpp', 'cdecl', 'redesenha a barra da posse da visão geral quando a posse muda (percentuais e a cor do clube com mais posse) e guarda o estado da partida na cópia do parâmetro 0x1d', 'redraws the overview possession bar when the share changes (percentages and the colour of the club with more of the ball) and stores the match state in the param 0x1d copy'), ('painel_da_visao_geral_da_partida', 'draw_match_overview_panel', '0x71c270', 'match_screens.cpp', 'cdecl', 'desenha a visão geral da partida: período, barra da posse e comentário, data, placar com intervalo/prorrogação/pênaltis, competição, autores dos gols e cartões, disputa de pênaltis, árbitro, público, tempo e partida abandonada', 'draws the match overview: period, possession bar and commentary, date, score with half time/extra time/penalties, competition, scorers and cards, shoot-out, referee, attendance, weather and abandoned match'), ('tabela_da_liga_ao_vivo', 'match_screens_draw_live_league_table', '0x7280e0', 'match_screens.cpp', 'cdecl', 'desenha a tabela da liga ao vivo (liga, topo, base) numa cópia da liga com os placares do dia aplicados (ou o aviso da data do sorteio): título, cabeçalhos, separadores, posição, seta de subida/descida, clube e colunas', 'draws the live league table (league, top, bottom) on a copy of the league with the day scores applied (or the draw date notice): title, headers, separators, position, up/down arrow, club and columns')]
ESCAPADAS = {}  # nome: (explicação pt, explicação en), quando houver
tot, ac, esc, ok = cadeia(N)
assert ok, 'cadeia sem a referencia'
assert set(esc) <= set(ESCAPADAS), ('explicar as escapadas', esc)
lac_pt = ' '.join(f'`{e}` escapou: {ESCAPADAS[e][0]}.' for e in esc) + (' (lacuna em `PENDENCIAS.md`)' if esc else '')
lac_en = ' '.join(f'`{e}` escaped: {ESCAPADAS[e][1]}.' for e in esc) + (' (gap in `PENDENCIAS.en.md`)' if esc else '')
M = (f"`mutacoes/leva{N}.py` ({tot}, pela carreira até 2002-06-01, confirmando no modo comparação as que escapam): {ac} acusadas. {lac_pt} "
     "Jogo real comparando até 2002-01-01: 0 divergências (963cea289f055ac3). Carreiras Rust ×2 e original até 2002-06-01: 2.382.029.053 sorteios, impressão 034ff3eb3e55dfd3, partidas b3ee24bdc00da55f, banco 7f2c15024cd99e7e")
ME = (f"`mutacoes/leva{N}.py` ({tot}, by the career to 2002-06-01, confirming the escaped ones in comparison mode): {ac} caught. {lac_en} "
      "Real game comparing to 2002-01-01: 0 divergences (963cea289f055ac3). Rust ×2 and original careers to 2002-06-01: 2,382,029,053 draws, fingerprint 034ff3eb3e55dfd3, matches b3ee24bdc00da55f, database 7f2c15024cd99e7e")
fazer(N, 500, 500 + len(R), 'as telas da partida (14): a montagem e a resposta da tela da partida ao vivo e a montagem da tela de detalhes; as telas da partida (13): a barra da posse, o painel da visão geral da partida e a tabela da liga ao vivo', 'the match screens (14): building and handling the live match screen and building the match details screen; the match screens (13): the possession bar, the match overview panel and the live league table',
      [f"| `{a}()` | {e} | {c} | {f}: {d} |" for a, _, e, f, c, d, _ in R],
      [f"| `{a}()` | {e} | {c} | {f}: {d} |" for a, _, e, f, c, _, d in R],
      M, ME, [(a, g) for a, g, *_ in R], "'posicao_no_conteiner': 'position_in_container',", secao=('Motor de partidas', 'Match engine'))
leia(N, 'as telas da partida (14): a montagem e a resposta da tela da partida ao vivo e a montagem da tela de detalhes; as telas da partida (13): a barra da posse, o painel da visão geral da partida e a tabela da liga ao vivo', 'the match screens (14): building and handling the live match screen and building the match details screen; the match screens (13): the possession bar, the match overview panel and the live league table', [(a, e, f + ', ' + c, dp, de) for a, _, e, f, c, dp, de in R], tot, ac, lac_pt, lac_en)
